 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const safeUrl=v=>{try{const u=new URL(String(v||''),W.location.href);return ['http:','https:'].includes(u.protocol)?u.href:'';}catch(_){return'';}};
 const list=k=>(store()?.get()?.[k]||[]).slice();
 function announce(message,tone='ready'){state.lastError=tone==='error'?message:null;if(q('status')){q('status').textContent=message;q('status').dataset.tone=tone;}Lab.InterfaceV0265?.announce?.(message,tone);}
 function providers(){return [...root().querySelectorAll('[data-discovery-provider]:checked')].map(x=>x.value);}
 function payload(){return{query:q('query').value.trim(),providers:providers(),maxResults:Number(q('limit').value||10),deduplicate:q('dedupe').checked,filters:{yearFrom:Number(q('yearFrom').value)||null,yearTo:Number(q('yearTo').value)||null,workType:q('type').value}};}
 function handoffUrl(kind,c){const title=encodeURIComponent(c?.title||q('query').value.trim());if(kind==='worldcat')return`https://search.worldcat.org/search?q=${title}`;if(kind==='scholar')return`https://scholar.google.com/scholar?q=${title}`;return c?.doi?`https://doi.org/${encodeURI(c.doi)}`:(safeUrl(c?.url)||'#');}
 function candidateKey(c){return c.fingerprint||c.doi||`${c.provider}:${c.providerId||c.title}`;}
 function renderHealth(){const providers=state.health?.providers||[];q('providers').innerHTML=providers.map(p=>`<article data-state="${p.configured?'ready':(p.handoffOnly?'handoff':'needs-config')}"><strong>${esc(p.label)}</strong><span>${esc(p.mode)}</span><small>${p.configured?'Configured':p.handoffOnly?'Handoff available':'Configuration required'}</small></article>`).join('')||'<p>Provider status will appear when the Python Compute Core responds.</p>';}
 function renderMetrics(){const imported=list('researchSources').filter(x=>x.externalDiscovery), searches=list('discoverySearches');q('metrics').innerHTML=[['Results',state.results.length],['Selected',state.selected.size],['Imported sources',imported.length],['Saved searches',searches.length]].map(x=>`<article><span>${x[0]}</span><strong>${x[1]}</strong></article>`).join('');}
 function resultCard(c){const key=candidateKey(c),checked=state.selected.has(key),authors=(c.authors||[]).join(', '),provider=(c.providers||[c.provider]).join(' · '),oa=c.isOpenAccess?`<span class="is-oa">Open access${c.openAccessStatus?` · ${esc(c.openAccessStatus)}`:''}</span>`:'<span>Access unknown</span>';return`<article class="sc-discovery0292-result"><label class="sc-discovery0292-select"><input type="checkbox" data-discovery-select="${esc(key)}" ${checked?'checked':''}><span class="screen-reader-text">Select ${esc(c.title)}</span></label><div><div class="sc-discovery0292-result-meta"><span>${esc(provider)}</span><span>${esc(c.year||'n.d.')}</span><span>${esc(c.workType||'work')}</span>${oa}</div><h4>${esc(c.title||'Untitled')}</h4><p>${esc(authors||c.publisher||'No creator metadata')}</p><p class="sc-discovery0292-citation">${esc(c.citation?.bibliography||'')}</p><div class="sc-discovery0292-links"><a href="${esc(handoffUrl('doi',c))}" target="_blank" rel="noopener">Record</a><a href="${esc(handoffUrl('worldcat',c))}" target="_blank" rel="noopener">WorldCat</a><a href="${esc(handoffUrl('scholar',c))}" target="_blank" rel="noopener">Scholar</a>${safeUrl(c.openAccessUrl)?`<a href="${esc(safeUrl(c.openAccessUrl))}" target="_blank" rel="noopener noreferrer">Open copy</a>`:''}<button type="button" data-discovery-oa="${esc(key)}">Check access</button></div><div class="sc-discovery0292-oa" data-discovery-oa-output="${esc(key)}"></div></div></article>`;}
 function renderResults(){q('results').innerHTML=state.results.map(resultCard).join('')||'<div class="sc-lab-empty-state"><h4>No discovery results</h4><p>Run a search across one or more configured metadata providers.</p></div>';root().querySelectorAll('[data-discovery-select]').forEach(el=>el.onchange=()=>{el.checked?state.selected.add(el.dataset.discoverySelect):state.selected.delete(el.dataset.discoverySelect);renderMetrics();});root().querySelectorAll('[data-discovery-oa]').forEach(el=>el.onclick=()=>lookupAccess(el.dataset.discoveryOa));renderMetrics();}
 function renderReports(){q('reports').innerHTML=(state.reports||[]).map(r=>`<li class="${r.ok?'is-ok':'is-error'}"><strong>${esc(r.provider)}</strong><span>${r.ok?`${r.count} result(s)`:esc(r.error||'Unavailable')}</span></li>`).join('')||'<li>No provider request has run.</li>';}
 async function loadHealth(){try{state.health=await Lab.ComputeClient.discoveryHealth();renderHealth();}catch(e){state.health={providers:[{label:'Crossref',mode:'live-api',configured:false},{label:'OpenAlex',mode:'live-api',configured:false},{label:'DataCite',mode:'live-api',configured:false},{label:'WorldCat',mode:'catalog-handoff',configured:true,handoffOnly:true}]};renderHealth();announce(`Discovery backend unavailable: ${e.message}`,'warning');}}
 async function runSearch(){try{const p=payload();if(p.query.length<2)throw new Error('Enter at least two search characters.');if(!p.providers.length)throw new Error('Select at least one live provider.');announce('Searching governed scholarly metadata providers…','working');const result=await Lab.ComputeClient.discoverySearch(p);state.results=result.candidates||[];state.reports=result.providerReports||[];state.selected.clear();store()?.add('discoverySearches',{id:uid('discovery-search'),schema:'sc-lab-external-discovery-search/0.29.2',version:V,recordType:'discovery-search',collection:'discoverySearches',query:p.query,providers:p.providers,filters:p.filters,resultCount:state.results.length,duplicatesRemoved:result.duplicatesRemoved||0,createdAt:now()},`Scholarly discovery search: ${p.query}`);renderResults();renderReports();announce(`${state.results.length} deduplicated result(s) returned.`);}catch(e){announce(e.message,'error');}}
 async function dedupe(){try{const result=Lab.ComputeClient?.discoveryDeduplicate?await Lab.ComputeClient.discoveryDeduplicate({candidates:state.results}):localDedupe(state.results);state.results=result.candidates||[];state.selected.clear();renderResults();announce(`${result.duplicatesRemoved||0} duplicate(s) removed.`);}catch(e){announce(e.message,'error');}}
 function localDedupe(rows){const map=new Map();rows.forEach(c=>{const key=(c.doi||`${String(c.title||'').toLowerCase()}:${c.year||''}`);if(!map.has(key))map.set(key,c);else{const a=map.get(key);a.providers=[...new Set([...(a.providers||[a.provider]),...(c.providers||[c.provider])])];}});return{candidates:[...map.values()],duplicatesRemoved:rows.length-map.size};}
 async function importSelected(){try{const selected=state.results.filter(c=>state.selected.has(candidateKey(c)));if(!selected.length)throw new Error('Select at least one result.');let imported=0;for(const c of selected){let source;try{source=(await Lab.ComputeClient.discoveryNormalize({candidate:c,projectId:store()?.get()?.id})).source;}catch(_){source={schema:'sc-lab-research-source/0.29.0',version:V,recordType:'research-source',collection:'researchSources',id:uid('src'),projectId:store()?.get()?.id,title:c.title,authors:c.authors||[],year:c.year||null,sourceType:c.workType||'scholarly-work',publisher:c.publisher||c.containerTitle||'',doi:c.doi||'',url:c.url||'',license:c.license||'',citation:c.citation||{},createdAt:now(),externalDiscovery:{schema:'sc-lab-discovery-source-import/0.29.2',providers:c.providers||[c.provider],fingerprint:c.fingerprint,isOpenAccess:c.isOpenAccess,openAccessStatus:c.openAccessStatus,openAccessUrl:c.openAccessUrl,retrievedAt:c.retrievedAt}};}if(list('researchSources').some(x=>(x.doi&&source.doi&&x.doi.toLowerCase()===source.doi.toLowerCase())||x.externalDiscovery?.fingerprint===source.externalDiscovery?.fingerprint))continue;store().add('researchSources',source,`Discovered source imported: ${source.title}`);store().add('discoveryCandidates',{...c,id:uid('candidate'),recordType:'discovery-candidate',collection:'discoveryCandidates',importedSourceId:source.id,importedAt:now()},`Discovery candidate retained: ${source.title}`);imported++;}store().add('sourceImportBatches',{id:uid('source-import'),schema:'sc-lab-discovery-source-import-batch/0.29.2',version:V,recordType:'source-import-batch',collection:'sourceImportBatches',candidateCount:selected.length,importedCount:imported,createdAt:now()},`${imported} scholarly source(s) imported`);state.selected.clear();renderResults();announce(`${imported} new source(s) imported into Evidence & provenance.`);}catch(e){announce(e.message,'error');}}
 async function lookupAccess(key){const c=state.results.find(x=>candidateKey(x)===key);if(!c)return;const out=root().querySelector(`[data-discovery-oa-output="${CSS.escape(key)}"]`);if(out)out.textContent='Checking access metadata…';try{const result=await Lab.ComputeClient.discoveryOpenAccess({candidate:c,doi:c.doi});const l=result.lookup||{};if(out)out.innerHTML=`<strong>${l.isOpenAccess?'Open access':'Access not confirmed'}</strong><span>${esc(l.status||'unknown')}</span>${safeUrl(l.bestUrl)?`<a href="${esc(safeUrl(l.bestUrl))}" target="_blank" rel="noopener noreferrer">Open available copy</a>`:''}`;store().add('openAccessLookups',{id:uid('oa'),schema:'sc-lab-open-access-lookup/0.29.2',version:V,recordType:'open-access-lookup',collection:'openAccessLookups',candidateFingerprint:c.fingerprint,doi:c.doi,lookup:l,createdAt:now()},`Open-access lookup: ${c.title}`);}catch(e){if(out)out.textContent=e.message;}}
 function saveProfile(){const profile={id:'library-profile-default',schema:'sc-lab-library-profile/0.29.2',version:V,recordType:'library-profile',collection:'libraryProfiles',institution:q('institution').value.trim(),openUrlResolver:q('resolver').value.trim(),notes:q('profileNotes').value.trim(),updatedAt:now()};const existing=list('libraryProfiles').find(x=>x.id===profile.id);existing?store().updateRecord(profile.id,profile,'Library profile updated'):store().add('libraryProfiles',profile,'Library profile created');announce('Library discovery profile saved locally to the active project.');}
 function loadProfile(){const p=list('libraryProfiles').find(x=>x.id==='library-profile-default');if(p){q('institution').value=p.institution||'';q('resolver').value=p.openUrlResolver||'';q('profileNotes').value=p.notes||'';}}
 function exportResults(){const project=store()?.get(),bundle={schema:'sc-lab-external-discovery-bundle/0.29.2',version:V,projectId:project?.id,query:payload(),exportedAt:now(),providerReports:state.reports,candidates:state.results};Lab.util.download(`${(project?.name||'project').replace(/[^a-z0-9]+/gi,'-')}-scholarly-discovery-v0292.json`,JSON.stringify(bundle,null,2),'application/json');announce('Discovery bundle exported.');}
 function mount(){const r=root();if(!r||r.dataset.discoveryV0292Mounted==='1')return false;r.dataset.discoveryV0292Mounted='1';q('search').onclick=runSearch;q('dedupeAction').onclick=dedupe;q('import').onclick=importSelected;q('export').onclick=exportResults;q('saveProfile').onclick=saveProfile;q('worldcat').onclick=()=>W.open(handoffUrl('worldcat'), '_blank','noopener,noreferrer');q('scholar').onclick=()=>W.open(handoffUrl('scholar'), '_blank','noopener,noreferrer');store()?.onChange(()=>{renderMetrics();loadProfile();});loadProfile();renderResults();renderReports();loadHealth();announce('External scholarly and data discovery workspace ready.');state.mounted=true;return true;}
 new MutationObserver(mount).observe(D.documentElement,{childList:true,subtree:true});D.readyState==='loading'?D.addEventListener('DOMContentLoaded',mount):mount();
 Lab.ExternalDiscoveryV0292={mount,status:()=>({version:V,mounted:!!root()?.dataset.discoveryV0292Mounted,results:state.results.length,selected:state.selected.size,error:state.lastError}),deduplicate:localDedupe};
