 function status(message,tone='ready'){const n=q('status');if(n){n.textContent=message;n.dataset.tone=tone;}Lab.InterfaceV0265?.announce?.(message,tone);}
 function csv(v){return String(v||'').split(',').map(x=>x.trim()).filter(Boolean);} function lines(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean);}
 function pairs(v){const out={};csv(v).forEach(token=>{const i=token.indexOf('=');if(i<1)throw new Error(`Expected symbol=value: ${token}`);const k=token.slice(0,i).trim(),n=Number(token.slice(i+1).trim());if(!/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(k)||!Number.isFinite(n))throw new Error(`Invalid numeric assignment: ${token}`);out[k]=n;});return out;}
 function bounds(v){const out={};csv(v).forEach(token=>{const i=token.indexOf('='),j=token.indexOf(':',i+1);if(i<1||j<0)throw new Error(`Expected symbol=lower:upper: ${token}`);const k=token.slice(0,i).trim(),lo=token.slice(i+1,j).trim(),hi=token.slice(j+1).trim();if(!/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(k))throw new Error(`Invalid bound symbol: ${k}`);const lower=lo===''?null:Number(lo),upper=hi===''?null:Number(hi);if((lower!==null&&!Number.isFinite(lower))||(upper!==null&&!Number.isFinite(upper))||(lower!==null&&upper!==null&&lower>upper))throw new Error(`Invalid bounds: ${token}`);out[k]={lower,upper};});return out;}
 function rows(){try{const v=JSON.parse(q('rows')?.value||'[]');if(!Array.isArray(v))throw 0;return v;}catch(_){throw new Error('Dataset rows must be a JSON array of objects.');}}
 async function api(path,body){const r=await fetch(`${apiRoot()}/compute/core/model-studio/${path}`,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':W.SCLabConfig?.nonce||''},body:body===undefined?undefined:JSON.stringify(body)});let j={};try{j=await r.json()}catch(_e){}if(!r.ok)throw new Error(j?.message||j?.detail||`Model Studio request failed (${r.status})`);return j;}
 function variables(){const features=csv(q('features')?.value),response=(q('response')?.value||'y').trim(),xu=(q('x-unit')?.value||'').trim(),yu=(q('y-unit')?.value||'').trim();return [...features.map((symbol,i)=>({symbol,label:symbol,unit:i===0?xu:'',role:'input'})),{symbol:response,label:response,unit:yu,role:'response'}];}
 function parameters(){const values=pairs(q('parameter-values')?.value||''),limits=bounds(q('parameter-bounds')?.value||'');return csv(q('parameters')?.value).map(symbol=>({symbol,label:symbol,unit:'',role:'estimated',value:Object.prototype.hasOwnProperty.call(values,symbol)?values[symbol]:null,bounds:limits[symbol]||{lower:null,upper:null}}));}
 function constants(){const values=pairs(q('constants')?.value||'');return Object.entries(values).map(([symbol,value])=>({symbol,label:symbol,unit:'',value}));}
 function initialConditions(){const values=pairs(q('initial-conditions')?.value||'');return Object.entries(values).map(([symbol,value])=>({symbol,value,unit:''}));}
 function bindings(){const features=csv(q('features')?.value),response=(q('response')?.value||'y').trim(),xu=(q('x-unit')?.value||'').trim(),yu=(q('y-unit')?.value||'').trim();return [...features.map((symbol,i)=>({column:symbol,symbol,role:'feature',unit:i===0?xu:''})),{column:response,symbol:response,role:'response',unit:yu}];}
 function buildModel(){return{schema:MODEL_SCHEMA,version:VERSION,recordType:'model-studio-model',id:state.model?.id||uid('model'),title:(q('title')?.value||'Scientific model').trim(),status:'draft',family:q('family')?.value||'declarative-expression',definition:{equation:(q('equation')?.value||'').trim(),registeredModelId:(q('registered-model')?.value||'').trim()},variables:variables(),parameters:parameters(),constants:constants(),initialConditions:initialConditions(),dataset:{datasetId:(q('dataset-id')?.value||'').trim()},datasetBindings:bindings(),assumptions:lines(q('assumptions')?.value),limitations:lines(q('limitations')?.value),provenance:{projectId:store()?.get()?.id||null,sourceIds:[],createdAt:state.model?.provenance?.createdAt||now(),updatedAt:now(),createdBy:''}};}
 function equationPayload(){const m=buildModel();return{equation:m.definition.equation,variables:m.variables,parameters:m.parameters,constants:m.constants,outputSymbol:(q('response')?.value||'y').trim()};}
 function renderModel(model){const m=model||state.model||buildModel();q('contract').textContent=JSON.stringify(m,null,2);const executable=m.definition?.safeExecution===true||m.family!=='declarative-expression';q('summary').innerHTML=`<article><span>Family</span><strong>${esc(m.family)}</strong></article><article><span>Variables</span><strong>${m.variables?.length||0}</strong></article><article><span>Parameters</span><strong>${m.parameters?.length||0}</strong></article><article><span>Executable</span><strong>${executable?'YES':'CHECK'}</strong></article>`;}
 function renderValidation(v){state.validation=v;const n=q('equation-validation');if(!n)return;n.innerHTML=`<strong>VALID EQUATION</strong><span>Output: ${esc(v.outputSymbol)}</span><span>Symbols: ${esc((v.referencedSymbols||[]).join(', ')||'none')}</span><span>Functions: ${esc((v.functions||[]).join(', ')||'none')}</span><span>Arbitrary code: NO</span>`;n.dataset.state='valid';}
