 async function preview(){status('Evaluating model preview…');await validate();const result=await api('equations/preview',{model:buildModel(),rows:rows()});state.model=result.model;state.graph=result.graph;renderModel(result.model);const engine=Lab.ScientificVisualizationEngineV0440;if(!engine)throw new Error('Shared Scientific Visualization Engine is unavailable.');engine.render(q('graph'),result.graph);q('graph-spec').textContent=JSON.stringify(result.graph,null,2);q('evaluated-rows').textContent=JSON.stringify(result.evaluation,null,2);status(`Equation preview evaluated ${result.evaluation?.rowCount||0} rows safely.`);return result;}
 function publicationSpec(){return{subtitle:(q('publication-subtitle')?.value||'').trim(),caption:(q('publication-caption')?.value||'').trim(),source:(q('publication-source')?.value||'').trim(),method:(q('publication-method')?.value||'').trim(),notes:(q('publication-notes')?.value||'').trim(),aspectRatio:q('publication-aspect')?.value||'16:9',showGrid:q('publication-grid')?.checked!==false,showLegend:q('publication-legend')?.checked!==false,background:'white'};}
 function applyPublication(){if(!state.graph)throw new Error('Evaluate or generate a scientific graph before applying publication settings.');state.graph={...state.graph,version:VERSION,schema:'sc-lab-scientific-graph/0.46.0',publication:publicationSpec(),interaction:{tooltip:true,focusablePoints:true,zoom:true,pan:true,crosshair:true,seriesToggle:true},exports:['svg','png','csv','json']};const engine=Lab.ScientificVisualizationEngineV0440;if(!engine)throw new Error('Interactive Scientific Visualization Engine v0.44.0 is unavailable.');engine.render(q('graph'),state.graph);q('graph-spec').textContent=JSON.stringify(state.graph,null,2);status('Publication figure settings applied. Use the graph toolbar to inspect, zoom, pan, or export.');return state.graph;}
