 function loadModel(model){
  if(!model||typeof model!=='object')throw new Error('A governed model object is required.');
  const vars=Array.isArray(model.variables)?model.variables:[],response=vars.find(v=>v?.role==='response')||vars.find(v=>v?.role==='output')||null,features=vars.filter(v=>v!==response&&v?.role!=='response'&&v?.role!=='output');
  const params=Array.isArray(model.parameters)?model.parameters:[],consts=Array.isArray(model.constants)?model.constants:[],ics=Array.isArray(model.initialConditions)?model.initialConditions:[];
  const set=(name,value)=>{const n=q(name);if(n)n.value=value??'';};
  set('title',model.title||'Imported Workbench model');set('family',model.family||'declarative-expression');set('equation',model.definition?.equation||'');set('registered-model',model.definition?.registeredModelId||'');
  set('features',features.map(v=>v.symbol).filter(Boolean).join(','));set('response',response?.symbol||model.definition?.outputSymbol||'y');set('x-unit',features[0]?.unit||'');set('y-unit',response?.unit||'');
  set('parameters',params.map(v=>v.symbol).filter(Boolean).join(','));set('parameter-values',params.filter(v=>v?.symbol&&Number.isFinite(Number(v.value))).map(v=>`${v.symbol}=${Number(v.value)}`).join(','));
  set('parameter-bounds',params.filter(v=>v?.symbol&&v.bounds&&(v.bounds.lower!==null&&v.bounds.lower!==undefined||v.bounds.upper!==null&&v.bounds.upper!==undefined)).map(v=>`${v.symbol}=${v.bounds?.lower??''}:${v.bounds?.upper??''}`).join(','));
  set('constants',consts.filter(v=>v?.symbol&&Number.isFinite(Number(v.value))).map(v=>`${v.symbol}=${Number(v.value)}`).join(','));set('initial-conditions',ics.filter(v=>v?.symbol&&Number.isFinite(Number(v.value))).map(v=>`${v.symbol}=${Number(v.value)}`).join(','));
  set('dataset-id',model.dataset?.datasetId||'');set('assumptions',(model.assumptions||[]).join('\n'));set('limitations',(model.limitations||[]).join('\n'));
  state.model=model;state.graph=null;state.validation=null;state.diagnostics=null;state.crossValidation=null;state.comparison=null;updateFamily();renderModel(model);
  q('equation-validation').textContent=model.definition?.safeExecution===true?'Imported equation was revalidated by the shared model contract.':'Validate the equation to inspect its safe execution contract.';q('equation-validation').dataset.state=model.definition?.safeExecution===true?'valid':'idle';
  status(`Model loaded into Model Studio: ${model.title||model.id||'Workbench model'}.`);return model;
 }
