  return{title:(q('title')?.value||'Scientific model').trim(),datasetId:(q('dataset-id')?.value||'').trim(),modelType,features,response,degree:Number(q('degree')?.value||2),objective:q('objective')?.value||'least-squares',holdoutFraction:0,seed:Number(q('seed')?.value||42),units:{[features[0]]:(q('x-unit')?.value||'').trim(),[response]:(q('y-unit')?.value||'').trim()}};
