 async function runDiagnostics(){const type=q('validation-model')?.value||'linear-multivariate';status('Running full-fit model diagnostics…');const result=await api('diagnostics/run',{study:validationStudy(type),rows:validationRows()});state.diagnostics=result.diagnostics;renderDiagnosticSummary(result.diagnostics,state.crossValidation);renderDiagnosticGraphs(result.diagnostics?.graphs||{});q('diagnostic-record').textContent=JSON.stringify(result.diagnostics,null,2);status(`Diagnostics complete: RMSE ${metric(result.diagnostics?.metrics?.rmse)}; ${result.diagnostics?.flaggedObservations?.length||0} standardized-residual flags.`);return result;}
