function explicitGraph(g){const candidates=[g?.provenanceGraph,g?.provenance_graph,g?.provenance?.graph,g?.provenance,g?.lineageGraph,g?.lineage_graph];for(const c of candidates){if(c&&Array.isArray(c.nodes)&&Array.isArray(c.edges))return{nodes:c.nodes.map(node),edges:c.edges.map(edge),source:'bound-scientific-object'}}return null}
function projectGraph(){const p=currentProject();if(!p||!Array.isArray(p.relationships)||!p.relationships.length)return null;const idx=new Map((p.recordIndex||[]).map(r=>[String(r.id),r]));const ids=new Set();const edges=p.relationships.slice(0,240).map((r,i)=>{ids.add(String(r.from));ids.add(String(r.to));return edge(r,i)});const nodes=[...ids].slice(0,160).map((id,i)=>{const r=idx.get(id)||store()?.getRecord?.(id)?.record||{};return node({id,type:r.recordType||r.collection||'project-record',label:r.title||r.name||id,detail:r.method||r.status||r.collection||'Lab project object',objectRef:id,metadata:{collection:r.collection||null,status:r.status||null}},i)});return nodes.length?{nodes,edges:edges.filter(e=>nodes.some(n=>n.id===e.from)&&nodes.some(n=>n.id===e.to)),source:'lab-project-relationships'}:null}
function fallbackGraph(g){const rows=Array.isArray(g?.data)?g.data:[],xf=g?.axes?.x?.field||'x',yf=g?.series?.[0]?.field||g?.axes?.y?.field||'y',source=g?.publication?.source||'Bound source',method=g?.publication?.method||'Declared method';const ns=[['source','SOURCE',source],['dataset','DATASET',`${rows.length} bound rows`],['transform','TRANSFORM','Declared pipeline'],['binding','BINDING',`${xf} → ${yf}`],['method','METHOD',method],['execution','EXECUTION','Scientific execution'],['uncertainty','UNCERTAINTY',g?.uncertainty?'Bound uncertainty':'Unbound'],['renderer','RENDERER','Renderer 3.1.0'],['figure','FIGURE',g?.title||'Scientific figure'],['evidence','EVIDENCE','Reference context'],['core','CORE REF','Platform Core reference']];const es=[['source','dataset','sourced-from'],['dataset','transform','transformed-by'],['dataset','binding','binds'],['transform','method','conditions'],['binding','method','maps'],['method','execution','executes'],['execution','uncertainty','quantifies'],['execution','renderer','visualizes'],['renderer','figure','renders'],['figure','evidence','supports'],['figure','core','registered-as']];return{nodes:ns.map(node),edges:es.map(edge),source:'derived-declared-lineage'}}
