function cacheRead(){try{return JSON.parse(W.localStorage?.getItem(CACHE)||'{}')||{}}catch(_){return{}}}
function cacheWrite(v){try{W.localStorage?.setItem(CACHE,JSON.stringify(v));S.cacheWrites++;return true}catch(_){return false}}
function stateValue(){return{layout:S.layout,selectedNode:S.selectedNode,selectedEdge:S.selectedEdge,traversal:S.traversal,relation:S.relation,scale:S.scale,tx:S.tx,ty:S.ty,updatedAt:new Date().toISOString()}}
function loadState(){const p=currentProject(),pid=p?.id||'unbound';S.lastProjectId=pid;const ps=p?.graphStudioPresentationState?.provenance||cacheRead()[pid]||{};S.layout=['layered','radial','swimlane'].includes(ps.layout)?ps.layout:'layered';S.selectedNode=ps.selectedNode||null;S.selectedEdge=ps.selectedEdge||null;S.traversal=['all','upstream','downstream','focus'].includes(ps.traversal)?ps.traversal:'all';S.relation=ps.relation||'all';S.scale=Number.isFinite(+ps.scale)?Math.max(.35,Math.min(3,+ps.scale)):1;S.tx=Number.isFinite(+ps.tx)?+ps.tx:0;S.ty=Number.isFinite(+ps.ty)?+ps.ty:0}
function persistCache(){const p=currentProject(),pid=p?.id||'unbound',all=cacheRead();all[pid]=stateValue();cacheWrite(all)}
function flushProjectPersistence(){S.persistTimer=null;const p=currentProject(),st=store();if(!p||!st?.update||S.persisting)return;const value=stateValue();S.persisting=true;try{st.update(pr=>{pr.graphStudioPresentationState=pr.graphStudioPresentationState||{};pr.graphStudioPresentationState.provenance=value;});S.projectPersistenceWrites++;}finally{S.persisting=false}}
function schedulePersist(){persistCache();if(S.persistTimer)W.clearTimeout(S.persistTimer);S.persistTimer=W.setTimeout(flushProjectPersistence,220)}
function adjacency(dir){const M=new Map();for(const n of S.model.nodes)M.set(n.id,[]);for(const e of S.model.edges){const a=dir==='upstream'?e.to:e.from,b=dir==='upstream'?e.from:e.to;if(M.has(a))M.get(a).push({node:b,edge:e})}return M}
function traversalResultFor(relation='all'){if(!S.model)return{nodes:new Set(),edges:new Set()};if(!S.selectedNode||S.traversal==='all'){const edges=new Set(S.model.edges.filter(e=>relation==='all'||e.relation===relation).map(e=>e.id));return{nodes:new Set(S.model.nodes.map(n=>n.id)),edges}}if(S.traversal==='focus')return{nodes:new Set([S.selectedNode]),edges:new Set()};const A=adjacency(S.traversal),nodes=new Set([S.selectedNode]),edges=new Set(),q=[S.selectedNode];while(q.length){const cur=q.shift();for(const x of A.get(cur)||[]){if(relation!=='all'&&x.edge.relation!==relation)continue;edges.add(x.edge.id);if(!nodes.has(x.node)){nodes.add(x.node);q.push(x.node)}}}return{nodes,edges}}
function traversalResult(){return traversalResultFor(S.relation)}
function visibilityResult(){return traversalResultFor(S.relation)}
function levels(){const indeg=new Map(S.model.nodes.map(n=>[n.id,0]));for(const e of S.model.edges)indeg.set(e.to,(indeg.get(e.to)||0)+1);const q=[...indeg].filter(([,d])=>d===0).map(([id])=>id),lev=new Map(q.map(id=>[id,0]));while(q.length){const a=q.shift(),L=lev.get(a)||0;for(const e of S.model.edges.filter(x=>x.from===a)){const nl=Math.max(lev.get(e.to)||0,L+1);lev.set(e.to,nl);indeg.set(e.to,(indeg.get(e.to)||1)-1);if(indeg.get(e.to)===0)q.push(e.to)}}for(const n of S.model.nodes)if(!lev.has(n.id))lev.set(n.id,0);return lev}
function positions(layout){const out={},nodes=S.model.nodes,N=Math.max(1,nodes.length);if(layout==='radial'){nodes.forEach((n,i)=>{const a=(i/N)*Math.PI*2-Math.PI/2;out[n.id]=[550+360*Math.cos(a),315+235*Math.sin(a)]});return out}if(layout==='swimlane'){const groups=new Map();for(const n of nodes){const k=String(n.type||'object');if(!groups.has(k))groups.set(k,[]);groups.get(k).push(n)}const lanes=[...groups.values()];lanes.forEach((arr,li)=>arr.forEach((n,ri)=>out[n.id]=[150+li*(820/Math.max(1,lanes.length-1)),110+ri*90]));return out}const lev=levels(),by=new Map();for(const n of nodes){const l=lev.get(n.id)||0;if(!by.has(l))by.set(l,[]);by.get(l).push(n)}const max=Math.max(0,...by.keys());for(const [l,arr] of by)arr.forEach((n,i)=>out[n.id]=[110+(l*(880/Math.max(1,max))),105+((i+1)*430/(arr.length+1))]);return out}
