function controls(){const ctx=relationshipContext();return`<div class="sc-gs13585-controls" data-gs13585-controls data-gs135853-context="ready"><strong>Native provenance explorer</strong>${['all','upstream','downstream','focus'].map(x=>`<button type="button" data-gs13585-traversal="${x}" class="${S.traversal===x?'is-active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}<select data-gs13585-relation aria-label="Relationship filter">${ctx.items.map(o=>`<option value="${esc(o.relation)}" data-gs135853-match-count="${o.count}" ${S.relation===o.relation?'selected':''} ${o.disabled?'disabled':''}>${esc(o.relation==='all'?'All relations':o.relation)}${o.relation!=='all'?` · ${o.count}`:''}</option>`).join('')}</select><span class="sc-gs135853-relation-state ${ctx.zeroMatch?'is-zero':''}" data-gs135853-relation-state aria-live="polite">${ctx.zeroMatch?`0 matching edges for ${esc(S.relation)} · ${esc(S.traversal)}`:`${ctx.currentMatchCount} matching edge${ctx.currentMatchCount===1?'':'s'}`}</span>${['layered','radial','swimlane'].map(x=>`<button type="button" data-gs13585-layout="${x}" class="${S.layout===x?'is-active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}<button type="button" data-gs13585-fit>Fit</button><button type="button" data-gs13585-zoom="in">+</button><button type="button" data-gs13585-zoom="out">−</button><button type="button" data-gs13585-clear>Clear focus</button><span class="sc-gs13585-status" data-gs13585-status><b>${S.model.nodes.length}</b> nodes · <b>${S.model.edges.length}</b> edges · ${esc(S.model.source)}</span></div>`}
function updateControls(){const t=S.target||stage();if(!t)return;for(const b of t.querySelectorAll('[data-gs13585-layout]'))b.classList.toggle('is-active',b.dataset.gs13585Layout===S.layout);for(const b of t.querySelectorAll('[data-gs13585-traversal]'))b.classList.toggle('is-active',b.dataset.gs13585Traversal===S.traversal);const ctx=relationshipContext(),sel=t.querySelector('[data-gs13585-relation]');if(sel){for(const opt of sel.options){const item=ctx.items.find(x=>x.relation===opt.value);if(!item)continue;opt.disabled=item.disabled;opt.dataset.gs135853MatchCount=String(item.count);opt.textContent=(item.relation==='all'?'All relations':item.relation)+(item.relation==='all'?'':` · ${item.count}`)}if(sel.value!==S.relation)sel.value=S.relation}const note=t.querySelector('[data-gs135853-relation-state]');if(note){note.classList.toggle('is-zero',ctx.zeroMatch);note.textContent=ctx.zeroMatch?`0 matching edges for ${S.relation} · ${S.traversal}`:`${ctx.currentMatchCount} matching edge${ctx.currentMatchCount===1?'':'s'}`}}
function updateSelection(){const t=S.target||stage();if(!t)return;for(const n of t.querySelectorAll('[data-gs13585-node]'))n.classList.toggle('is-selected',n.dataset.gs13585Node===S.selectedNode);for(const e of t.querySelectorAll('[data-gs13585-edge]'))e.classList.toggle('is-selected',e.dataset.gs13585Edge===S.selectedEdge);renderInspector()}
function updateVisibility(){const t=S.target||stage();if(!t||!S.model)return;const vis=visibilityResult();for(const n of t.querySelectorAll('[data-gs13585-node]'))n.classList.toggle('is-muted',!vis.nodes.has(n.dataset.gs13585Node));for(const eg of t.querySelectorAll('[data-gs13585-edge]')){const active=vis.edges.has(eg.dataset.gs13585Edge);eg.classList.toggle('is-muted',!active);eg.querySelector('.sc-gs13585-edge')?.classList.toggle('is-muted',!active);eg.querySelector('.sc-gs13585-edge-label')?.classList.toggle('is-muted',!active)}return vis}
function updateLayout(){const t=S.target||stage();if(!t||!S.model)return false;S.positions=positions(S.layout);for(const n of t.querySelectorAll('[data-gs13585-node]')){const p=S.positions[n.dataset.gs13585Node];if(p)n.setAttribute('transform',`translate(${p[0]-68},${p[1]-29})`)}for(const eg of t.querySelectorAll('[data-gs13585-edge]')){const e=S.model.edges.find(x=>x.id===eg.dataset.gs13585Edge);if(!e)continue;const A=S.positions[e.from],B=S.positions[e.to];if(!A||!B)continue;const line=eg.querySelector('line'),label=eg.querySelector('text');line?.setAttribute('x1',A[0]);line?.setAttribute('y1',A[1]);line?.setAttribute('x2',B[0]);line?.setAttribute('y2',B[1]);label?.setAttribute('x',(A[0]+B[0])/2);label?.setAttribute('y',(A[1]+B[1])/2-6)}return true}
