function selectNode(id){if(!S.model?.nodeMap.has(id))return false;S.selectedNode=id;S.selectedEdge=null;return incremental('node-selection',{controls:true,selection:true,visibility:S.traversal!=='all',layout:false,camera:false,persist:true})}
