function setLayout(v){if(!['layered','radial','swimlane'].includes(v)||S.layout===v)return true;S.layout=v;return incremental('layout',{controls:true,selection:false,visibility:false,layout:true,camera:false,inspector:false,persist:true})}
function setTraversal(v){if(!['all','upstream','downstream','focus'].includes(v))return false;S.traversal=v;return incremental('traversal',{controls:true,selection:false,visibility:true,layout:false,camera:false,inspector:false,persist:true})}
function setRelation(v){const next=relOptions().includes(v)?v:'all';if(S.relation===next){updateControls();return true}S.relation=next;return incremental('relationship-filter',{controls:true,selection:false,visibility:true,layout:false,camera:false,inspector:false,persist:true})}
function zoom(delta){S.scale=Math.max(.35,Math.min(3,S.scale*delta));return incremental('zoom',{controls:false,selection:false,visibility:false,layout:false,camera:true,inspector:false,persist:true})}
