 function sourceForm(){const identifiers={};[['doi','doi'],['pmid','pmid'],['arxiv','arxiv'],['isbn','isbn']].forEach(([k,f])=>{const v=q(f)?.value.trim();if(v)identifiers[k]=v;});return{id:q('source-id')?.value.trim()||`source-${collection('scientificLiteratureSourcesV0630').length+1}`,sourceType:q('source-type')?.value||'journal-article',title:q('title')?.value.trim()||'',authors:split(q('authors')?.value),publicationYear:q('year')?.value||'',containerTitle:q('container')?.value.trim()||'',publisher:q('publisher')?.value.trim()||'',identifiers,sourceUrl:q('url')?.value.trim()||'',origin:q('origin')?.value||'manual',libraryRecordRef:q('library-ref')?.value.trim()||'',status:q('source-status')?.value||'unknown',peerReviewStatus:q('peer-review')?.value||'unknown',scopeNote:q('scope')?.value.trim()||'',reviewHistory:state.source?.reviewHistory||[]};}
