 function newSource(){state.source=null;const n=collection('scientificLiteratureSourcesV0630').length+1;const fields={'source-id':`source-${n}`,title:'',authors:'',year:'',container:'',publisher:'',doi:'',pmid:'',arxiv:'',isbn:'',url:'','library-ref':'',scope:'','review-rationale':''};Object.entries(fields).forEach(([k,v])=>{const x=q(k);if(x)x.value=v;});if(q('source-type'))q('source-type').value='journal-article';if(q('origin'))q('origin').value='manual';if(q('source-status'))q('source-status').value='unknown';if(q('peer-review'))q('peer-review').value='unknown';status('New literature source form ready. Bibliographic metadata is researcher-supplied unless imported by another governed connector.');}
 async function saveSource(){const r=await api('normalize-source',{source:sourceForm()});state.source=r.source;populateSource(r.source);upsert('scientificLiteratureSourcesV0630',{...r.source,recordType:'scientific-literature-source-v0630'},'v0.63 literature source saved.');status(`Literature source saved · ${r.source.id} · human source review still governs inclusion.`);return r.source;}
 async function reviewSource(){await saveSource();const decision=q('review-decision')?.value||'include',rationale=q('review-rationale')?.value.trim()||'';const r=await api('review-source',{source:state.source,review:{decision,rationale,reviewerRole:'researcher',reviewedAt:now()}});state.source=r.source;populateSource(r.source);upsert('scientificLiteratureSourcesV0630',{...r.source,recordType:'scientific-literature-source-v0630'},'v0.63 literature source review recorded.');if(q('review-rationale'))q('review-rationale').value='';status(`Source review recorded: ${r.source.id} → ${decision}.`);}
 function refreshSelects(){const sources=collection('scientificLiteratureSourcesV0630'),claims=collection('scientificClaimsV0620');for(const name of ['link-source','edge-from','edge-to']){const n=q(name);if(n){const old=n.value;n.innerHTML=sources.map(s=>`<option value="${esc(s.id)}">${esc(s.id)} · ${esc(s.title||'Untitled')}</option>`).join('');if(sources.some(s=>s.id===old))n.value=old;}}const c=q('link-claim');if(c){const old=c.value;c.innerHTML=claims.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} · ${esc(String(x.statement||'').slice(0,90))}</option>`).join('');if(claims.some(x=>x.id===old))c.value=old;}}
 async function addClaimLink(){const claimId=q('link-claim')?.value,sourceId=q('link-source')?.value;if(!claimId||!sourceId)throw new Error('Save at least one v0.62 claim and one v0.63 literature source first.');const claim=collection('scientificClaimsV0620').find(x=>x.id===claimId),source=collection('scientificLiteratureSourcesV0630').find(x=>x.id===sourceId);const link={claimId,sourceId,role:q('link-role')?.value||'supports',locator:q('link-locator')?.value.trim()||'',note:q('link-note')?.value.trim()||'',claimHash:claim?.claimHash||'',sourceHash:source?.sourceHash||''};const r=await api('normalize-claim-link',{link});upsert('scientificLiteratureClaimLinksV0630',{...r.link,recordType:'source-claim-provenance-v0630'},'v0.63 source-to-claim provenance saved.');status(`Source-to-claim provenance saved · ${claimId} ← ${sourceId} (${r.link.role}).`);}
