 function renderEvaluation(e){const m=q('metrics');if(m)m.innerHTML=[['Gate',e?.gate||'—'],['Sources',e?.sourceCount||0],['Claim links',e?.claimLinkCount||0],['Citation edges',e?.citationEdgeCount||0],['Duplicates',(e?.duplicateIdentifierGroups||[]).length]].map(([a,b])=>`<article><span>${esc(a)}</span><strong>${esc(b)}</strong></article>`).join('');const rows=q('claim-matrix');if(rows)rows.innerHTML=(e?.claimRows||[]).map(x=>`<tr><td>${esc(x.claimId)}</td><td>${esc(x.gate)}</td><td>${x.sourceLinkCount}</td><td>${x.reviewedSourceLinkCount}</td><td>${x.contradictingSourceCount}</td><td>${esc((x.unresolvedSourceIds||[]).join(', ')||'—')}</td></tr>`).join('')||'<tr><td colspan="6">No v0.62 claims found.</td></tr>';const out=q('output');if(out)out.textContent=JSON.stringify(e,null,2);}
