 function saveEvidence(){if(!state.packet)throw new Error('Build the literature provenance packet first.');const s=store();if(!s)throw new Error('Project store unavailable.');s.add('analysisPackets',{recordType:'scientific-literature-provenance-v0630',title:'Scientific Literature & Source-to-Claim Provenance',analysis:{version:VERSION,gate:state.packet.gate,citationGraphHash:state.packet.citationGraphHash,evaluationHash:state.packet.evaluationHash,packetHash:state.packet.packetHash,sourceCount:state.packet.sourceRecords?.length||0,claimLinkCount:state.packet.claimLinks?.length||0,citationEdgeCount:state.packet.citationEdges?.length||0,boundaries:state.packet.boundaries}},'v0.63 literature provenance saved.');status('Literature provenance evidence saved to analysisPackets; full text and credentials were not copied.');}
 function renderSources(){const n=q('sources');const sources=collection('scientificLiteratureSourcesV0630');if(n)n.innerHTML=sources.slice(0,60).map(s=>{const rv=(s.reviewHistory||[]).at(-1)?.decision||'unreviewed';return`<div><span><strong>${esc(s.id)}</strong> · ${esc(s.title||'Untitled')} <small>${esc(rv)}</small></span><button type="button" class="sc-lab-button" data-lit-v0630-load-source="${esc(s.id)}">Load</button></div>`;}).join('')||'<p>No v0.63 literature sources saved.</p>';}
