      (events||[]).forEach((v,index)=>{E+=num(v.E,`vector ${index+1} E`);px+=num(v.px||0,`vector ${index+1} px`);py+=num(v.py||0,`vector ${index+1} py`);pz+=num(v.pz||0,`vector ${index+1} pz`);});const m2=E*E-px*px-py*py-pz*pz;
