    rocheLimit({primaryRadiusM,primaryDensity,satelliteDensity,bodyType}) { const R=positive(primaryRadiusM,'Primary radius'),rhoM=positive(primaryDensity,'Primary density'),rhom=positive(satelliteDensity,'Satellite density'); const k=String(bodyType)==='rigid'?1.26:2.44; return {rocheLimitM:round(k*R*Math.cbrt(rhoM/rhom),10),model:String(bodyType)==='rigid'?'rigid':'fluid'}; },
    hohmannTransfer({r1M,r2M,mu}) { const r1=positive(r1M,'Initial radius'),r2=positive(r2M,'Final radius'),gm=positive(mu,'Gravitational parameter'); const at=(r1+r2)/2; const v1=Math.sqrt(gm/r1),v2=Math.sqrt(gm/r2),vt1=Math.sqrt(gm*(2/r1-1/at)),vt2=Math.sqrt(gm*(2/r2-1/at)); return {deltaV1MS:round(Math.abs(vt1-v1),10),deltaV2MS:round(Math.abs(v2-vt2),10),totalDeltaVMS:round(Math.abs(vt1-v1)+Math.abs(v2-vt2),10),transferTimeSeconds:round(Math.PI*Math.sqrt(at**3/gm),10)}; },
    transitDepth({planetRadiusJupiter,starRadiusSolar}) { const rp=positive(planetRadiusJupiter,'Planet radius')*C.Rj,rs=positive(starRadiusSolar,'Star radius')*C.Rsun,depth=(rp/rs)**2; return {fraction:round(depth,12),percent:round(depth*100,10),ppm:round(depth*1e6,10)}; },
    radialVelocityAmplitude({planetMassJupiter,periodDays,starMassSolar,inclinationDeg,eccentricity}) { const mp=positive(planetMassJupiter,'Planet mass')*C.Mj,P=positive(periodDays,'Period')*C.day,ms=positive(starMassSolar,'Star mass')*C.Msun,e=clamp(n(eccentricity),0,0.999999),si=Math.sin(rad(inclinationDeg)); const K=(2*Math.PI*C.G/P)**(1/3)*mp*si/(ms+mp)**(2/3)/Math.sqrt(1-e*e); return {semiAmplitudeMS:round(K,10)}; },
    equilibriumTemperature({starTempK,starRadiusSolar,distanceAu,albedo,redistribution}) { const T=positive(starTempK,'Stellar temperature'),R=positive(starRadiusSolar,'Stellar radius')*C.Rsun,a=positive(distanceAu,'Distance')*C.au,A=clamp(n(albedo),0,1),f=positive(redistribution,'Redistribution factor'); return {equilibriumTemperatureK:round(T*Math.sqrt(R/(2*a))*Math.pow((1-A)/f,0.25),10)}; },
    stefanLuminosity({radiusSolar,tempK}) { const R=positive(radiusSolar,'Radius')*C.Rsun,T=positive(tempK,'Temperature'),L=4*Math.PI*R*R*C.sigma*T**4; return {luminosityW:round(L,10),luminositySolar:round(L/C.Lsun,10)}; },
    fluxAtDistance({luminositySolar,distancePc}) { const L=positive(luminositySolar,'Luminosity')*C.Lsun,d=positive(distancePc,'Distance')*C.pc; return {fluxWM2:round(L/(4*Math.PI*d*d),10)}; },
    wienPeak({tempK}) { const T=positive(tempK,'Temperature'),lambda=2.897771955e-3/T; return {peakWavelengthM:round(lambda,10),peakWavelengthNm:round(lambda*1e9,10)}; },
    mainSequenceLifetime({massSolar}) { const M=positive(massSolar,'Mass'); return {lifetimeYears:round(1e10*Math.pow(M,-2.5),10)}; },
    surfaceGravity({massSolar,radiusSolar}) { const M=positive(massSolar,'Mass')*C.Msun,R=positive(radiusSolar,'Radius')*C.Rsun,g=C.G*M/(R*R); return {gravityMS2:round(g,10),logGCgs:round(Math.log10(g*100),10)}; },
    schwarzschildRadius({massSolar}) { const M=positive(massSolar,'Mass')*C.Msun; return {radiusM:round(2*C.G*M/C.c**2,10),radiusKm:round(2*C.G*M/C.c**2/1000,10)}; },
    eddingtonLuminosity({massSolar}) { const M=positive(massSolar,'Mass'); return {luminosityW:round(1.26e31*M,10),luminositySolar:round(1.26e31*M/C.Lsun,10)}; },
    magnitudeFluxRatio({magnitude1,magnitude2}) { const ratio=Math.pow(10,-0.4*(n(magnitude1)-n(magnitude2))); return {flux1OverFlux2:round(ratio,12)}; },
    distanceModulus({distancePc}) { const d=positive(distancePc,'Distance'); return {distanceModulus:round(5*Math.log10(d)-5,10)}; },
    absoluteMagnitude({apparentMagnitude,distancePc,extinctionMag}) { const d=positive(distancePc,'Distance'); return {absoluteMagnitude:round(n(apparentMagnitude)-5*Math.log10(d)+5-n(extinctionMag),10)}; },
    photometricSnr({sourceElectrons,skyElectrons,darkElectrons,readNoiseElectrons,aperturePixels,exposures}) { const S=Math.max(0,n(sourceElectrons)),sky=Math.max(0,n(skyElectrons)),dark=Math.max(0,n(darkElectrons)),rn=Math.max(0,n(readNoiseElectrons)),pix=positive(aperturePixels,'Aperture pixels'),N=positive(exposures,'Exposures'); const signal=S*N,variance=(S+sky+dark)*N+pix*N*rn*rn; return {signalElectrons:round(signal,10),noiseElectrons:round(Math.sqrt(variance),10),snr:round(signal/Math.sqrt(variance),10)}; },
    aperturePhotometry({apertureCounts,skyPerPixel,aperturePixels,gain}) { const net=n(apertureCounts)-n(skyPerPixel)*positive(aperturePixels,'Aperture pixels'); return {netCounts:round(net,10),netElectrons:round(net*positive(gain,'Gain'),10)}; },
    dopplerShift({restWavelength,observedWavelength}) { const l0=positive(restWavelength,'Rest wavelength'),l=positive(observedWavelength,'Observed wavelength'),z=l/l0-1; return {redshift:round(z,12),classicalVelocityKmS:round(z*C.c/1000,10)}; },
    resolvingPower({wavelength,deltaWavelength}) { return {resolvingPower:round(positive(wavelength,'Wavelength')/positive(deltaWavelength,'Resolution element'),10)}; },
    equivalentWidth({wavelengths,fluxes,continuum}) { const x=arr(wavelengths).map(Number),y=arr(fluxes).map(Number),c=positive(continuum,'Continuum'); if(x.length!==y.length||x.length<2)throw new Error('Wavelength and flux arrays must have equal length >= 2.'); let ew=0; for(let i=1;i<x.length;i++) ew+=(1-(y[i-1]+y[i])/(2*c))*(x[i]-x[i-1]); return {equivalentWidth:round(ew,10)}; },
    blackbodySpectrum({tempK,minNm,maxNm,points}) { const T=positive(tempK,'Temperature'),lo=positive(minNm,'Minimum wavelength'),hi=positive(maxNm,'Maximum wavelength'),N=Math.max(20,Math.min(400,Math.round(positive(points,'Points')))); if(hi<=lo)throw new Error('Maximum wavelength must exceed minimum.'); const series=[]; for(let i=0;i<N;i++){const nm=lo+(hi-lo)*i/(N-1),lam=nm*1e-9,B=2*C.h*C.c*C.c/(lam**5)/(Math.exp(C.h*C.c/(lam*C.k*T))-1);series.push({x:nm,intensity:B});} const max=Math.max(...series.map(p=>p.intensity)); series.forEach(p=>p.intensity/=max); return {peakWavelengthNm:round(2.897771955e6/T,10),series}; },
    hubbleDistance({redshift,h0}) { const z=n(redshift),H=positive(h0,'Hubble constant'); if(z<0)throw new Error('Redshift must be nonnegative.'); return {distanceMpc:round((299792.458*z)/H,10),recessionVelocityKmS:round(299792.458*z,10)}; },
