    virialMass({velocityDispersionKmS,radiusKpc}) { const v=positive(velocityDispersionKmS,'Velocity dispersion')*1000,R=positive(radiusKpc,'Radius')*1000*C.pc,M=5*R*v*v/C.G; return {virialMassKg:round(M,10),virialMassSolar:round(M/C.Msun,10)}; },
    rotationMass({velocityKmS,radiusKpc}) { const v=positive(velocityKmS,'Velocity')*1000,R=positive(radiusKpc,'Radius')*1000*C.pc,M=v*v*R/C.G; return {enclosedMassKg:round(M,10),enclosedMassSolar:round(M/C.Msun,10)}; },
    diffractionLimit({wavelengthNm,diameterM}) { const th=1.22*positive(wavelengthNm,'Wavelength')*1e-9/positive(diameterM,'Aperture'); return {radians:round(th,12),arcseconds:round(th*206264.806,10)}; },
    plateScale({pixelMicron,focalLengthMm}) { return {arcsecPerPixel:round(206.265*positive(pixelMicron,'Pixel size')/positive(focalLengthMm,'Focal length'),10)}; },
    fieldOfView({sensorWidthMm,focalLengthMm}) { const angle=2*Math.atan(positive(sensorWidthMm,'Sensor width')/(2*positive(focalLengthMm,'Focal length'))); return {fieldDegrees:round(deg(angle),10),fieldArcminutes:round(deg(angle)*60,10)}; },
    stackingSnr({singleExposureSnr,exposures}) { return {combinedSnr:round(positive(singleExposureSnr,'Single-exposure SNR')*Math.sqrt(positive(exposures,'Exposures')),10)}; },
    exposureSaturation({sourceRateElectronsS,fullWellElectrons,safetyFraction}) { const rate=positive(sourceRateElectronsS,'Source rate'),well=positive(fullWellElectrons,'Full well'),f=clamp(n(safetyFraction),0.01,1); return {maximumExposureSeconds:round(well*f/rate,10)}; }
