  function validate(def,input,result){const warnings=[];let status='validated';if(Object.values(result).some(v=>typeof v==='number'&&!Number.isFinite(v))){status='invalid';warnings.push('The numerical result is not finite.');} if(['hubbleDistance','lookbackLowZ'].includes(def.id)&&n(input.redshift)>0.1){status='warning';warnings.push('Low-redshift approximation is being used above z=0.1.');} if(def.id==='radialVelocityAmplitude'&&n(input.planetMassJupiter)>20){status='warning';warnings.push('Companion mass is in the brown-dwarf or stellar regime; planet approximation may be misleading.');} if(def.id==='equilibriumTemperature')warnings.push('No greenhouse effect or internal heat source is included.'); if(def.id==='mainSequenceLifetime')warnings.push('Power-law lifetime is only an order-of-magnitude main-sequence estimate.'); if(def.id==='dopplerShift'&&Math.abs(result.redshift)>0.01){status='warning';warnings.push('Classical velocity is inaccurate at larger redshift; use a relativistic relation.');} result._validation={status,method:def.name,warnings,constantsVersion:'CODATA/SI 2019 constants; astronomy release 0.6.0'};return result;}
