    evi({nir,red,blue}) { const den=n(nir)+6*n(red)-7.5*n(blue)+1;if(!den)throw new Error('EVI denominator cannot equal zero.');return {evi:round(2.5*(n(nir)-n(red))/den)}; },
    broadbandAlbedo({reflectances,weights}) { const r=list(reflectances),w0=list(weights);if(!r.length||r.length!==w0.length)throw new Error('Reflectances and weights must have matching lengths.');const sw=w0.reduce((s,v)=>s+v,0);if(!sw)throw new Error('Weights must sum to a nonzero value.');return {albedo:round(r.reduce((s,v,i)=>s+v*w0[i],0)/sw)}; },
    brightnessTemperature({radiance,k1,k2}) { const L=positive(radiance,'Radiance'),K1=positive(k1,'K1'),K2=positive(k2,'K2');const T=K2/Math.log(K1/L+1);return {brightnessTemperatureK:round(T),brightnessTemperatureC:round(T-273.15)}; },
    toaReflectance({radiance,earthSunDistanceAu,solarIrradiance,solarZenithDeg}) { const mu=Math.cos(n(solarZenithDeg)*Math.PI/180);if(mu<=0)throw new Error('Solar zenith must be below 90 degrees.');return {toaReflectance:round(Math.PI*nonnegative(radiance,'Radiance')*positive(earthSunDistanceAu,'Earth-Sun distance')**2/(positive(solarIrradiance,'Solar irradiance')*mu))}; },
    classificationMetrics({truePositive,falsePositive,trueNegative,falseNegative}) { const tp=nonnegative(truePositive,'True positives'),fp=nonnegative(falsePositive,'False positives'),tn=nonnegative(trueNegative,'True negatives'),fn=nonnegative(falseNegative,'False negatives'),N=tp+fp+tn+fn;if(!N)throw new Error('At least one classified sample is required.');const precision=tp/(tp+fp||1),recall=tp/(tp+fn||1);return {accuracy:round((tp+tn)/N),precision:round(precision),recall:round(recall),f1:round(2*precision*recall/(precision+recall||1)),specificity:round(tn/(tn+fp||1))}; },
    pixelArea({pixelCount,resolutionM}) { const area=nonnegative(pixelCount,'Pixel count')*positive(resolutionM,'Resolution')**2;return {areaM2:round(area),areaHa:round(area/1e4),areaKm2:round(area/1e6)}; },
    radiometricCalibration({digitalNumber,gain,bias}) { return {radiance:round(n(gain)*n(digitalNumber)+n(bias))}; },
    surfaceTemperature({brightnessTempK,wavelengthUm,emissivity}) { const Tb=positive(brightnessTempK,'Brightness temperature'),lambda=positive(wavelengthUm,'Wavelength')*1e-6,e=positive(emissivity,'Emissivity');if(e>1)throw new Error('Emissivity cannot exceed 1.');const rho=1.438776877e-2,T=Tb/(1+(lambda*Tb/rho)*Math.log(e));return {surfaceTemperatureK:round(T),surfaceTemperatureC:round(T-273.15)}; },

    recurrenceProbability({returnPeriodYr,years}) { const T=positive(returnPeriodYr,'Return period'),y=positive(years,'Years');if(T<=1)throw new Error('Return period must exceed one year.');return {exceedanceProbability:round(1-Math.pow(1-1/T,y))}; },
    landslideFactorSafety({cohesionKPa,areaM2,weightKN,slopeDeg,porePressureKPa,frictionDeg}) { const A=positive(areaM2,'Area'),W=positive(weightKN,'Weight')*1000,th=n(slopeDeg)*Math.PI/180,u=nonnegative(porePressureKPa,'Pore pressure')*1000,phi=n(frictionDeg)*Math.PI/180;const resisting=nonnegative(cohesionKPa,'Cohesion')*1000*A+(W*Math.cos(th)-u*A)*Math.tan(phi),driving=W*Math.sin(th);if(driving<=0)throw new Error('Driving force must be positive.');const fs=resisting/driving;return {factorOfSafety:round(fs),classification:fs<1?'unstable':fs<1.3?'marginal':'nominally stable'}; },
    ashSettling({particleDiameterUm,particleDensityKgM3,airDensityKgM3,dynamicViscosityPaS}) { const d=positive(particleDiameterUm,'Particle diameter')*1e-6,r=d/2,v=2*(positive(particleDensityKgM3,'Particle density')-positive(airDensityKgM3,'Air density'))*g*r*r/(9*positive(dynamicViscosityPaS,'Dynamic viscosity'));return {stokesSettlingVelocityMS:round(v),_warnings:['Stokes settling is valid only for low particle Reynolds number and spherical particles.']}; },
    stormSurgeSetup({windSpeedMS,dragCoefficient,fetchKm,waterDepthM,airDensityKgM3,waterDensityKgM3}) { const tau=positive(airDensityKgM3,'Air density')*positive(dragCoefficient,'Drag coefficient')*positive(windSpeedMS,'Wind speed')**2,eta=tau*positive(fetchKm,'Fetch')*1000/(positive(waterDensityKgM3,'Water density')*g*positive(waterDepthM,'Water depth'));return {windStressNm2:round(tau),setupM:round(eta),_warnings:['One-dimensional wind setup omits pressure, wave, bathymetry, and coastal-geometry effects.']}; },
    beachRunup({slope,significantWaveHeightM,periodS}) { const L0=g*positive(periodS,'Period')**2/(2*Math.PI),R2=1.1*(0.35*n(slope)*Math.sqrt(positive(significantWaveHeightM,'Wave height')*L0)+Math.sqrt(positive(significantWaveHeightM,'Wave height')*L0*(0.563*n(slope)**2+0.004))/2);return {deepWaterWavelengthM:round(L0),runup2PercentM:round(R2),_warnings:['Empirical runup screening requires a representative beach slope and offshore wave state.']}; },
    contaminantAdvection({velocityMS,dispersionM2S,timeHours}) { const t=positive(timeHours,'Time')*3600;return {plumeCenterM:round(n(velocityMS)*t),oneSigmaSpreadM:round(Math.sqrt(2*nonnegative(dispersionM2S,'Dispersion')*t))}; },
    spillArea({volumeM3,meanThicknessMm}) { const A=positive(volumeM3,'Volume')/(positive(meanThicknessMm,'Thickness')/1000);return {areaM2:round(A),areaKm2:round(A/1e6)}; },

    atmosphericCO2Mass({concentrationChangePpm,gtCO2PerPpm}) { return {atmosphericCO2ChangeGt:round(n(concentrationChangePpm)*positive(gtCO2PerPpm,'Conversion factor'))}; },
    emissionsToPpm({emissionsGtCO2,airborneFraction,gtCO2PerPpm}) { return {concentrationIncreasePpm:round(nonnegative(emissionsGtCO2,'Emissions')*fraction(airborneFraction,'Airborne fraction')/positive(gtCO2PerPpm,'Conversion factor'))}; },
    ecosystemCarbonStock({carbonDensityKgM2,areaKm2}) { const kg=nonnegative(carbonDensityKgM2,'Carbon density')*positive(areaKm2,'Area')*1e6;return {carbonStockT:round(kg/1000),carbonStockGt:round(kg/1e12)}; },
    sequestration({rateTCO2HaYr,areaHa,years}) { return {sequesteredTCO2:round(n(rateTCO2HaYr)*positive(areaHa,'Area')*positive(years,'Years'))}; },
    soilOrganicCarbon({carbonFraction,bulkDensityKgM3,depthM,areaHa,rockFraction}) { const mass=positive(bulkDensityKgM3,'Bulk density')*positive(depthM,'Depth')*positive(areaHa,'Area')*1e4*(1-fraction(rockFraction,'Rock fraction'))*fraction(carbonFraction,'Carbon fraction');return {soilCarbonT:round(mass/1000),soilCO2EquivalentT:round(mass/1000*44/12)}; },
    methaneCO2e({methaneT,gwp}) { return {co2EquivalentT:round(n(methaneT)*positive(gwp,'GWP'))}; },
    oceanCarbonFlux({fluxMolCM2Yr,areaKm2}) { const mol=n(fluxMolCM2Yr)*positive(areaKm2,'Area')*1e6,kgC=mol*0.012011;return {carbonFluxTPerYr:round(kgC/1000),carbonFluxGtPerYr:round(kgC/1e12)}; }
