    researchQualityVerify(payload) { return request(endpoint('researchQualityVerify'), { method:'POST', body:payload, timeoutMs:65000 }); },
    researchQualityCompare(payload) { return request(endpoint('researchQualityCompare'), { method:'POST', body:payload, timeoutMs:65000 }); },
    discoveryHealth() { return request(endpoint('discoveryHealth')); },
    discoveryProviders() { return request(endpoint('discoveryProviders')); },
    discoverySearch(payload) { return request(endpoint('discoverySearch'), { method:'POST', body:payload, timeoutMs:65000 }); },
    discoveryNormalize(payload) { return request(endpoint('discoveryNormalize'), { method:'POST', body:payload, timeoutMs:65000 }); },
    discoveryDeduplicate(payload) { return request(endpoint('discoveryDeduplicate'), { method:'POST', body:payload, timeoutMs:65000 }); },
    discoveryOpenAccess(payload) { return request(endpoint('discoveryOpenAccess'), { method:'POST', body:payload, timeoutMs:65000 }); },
    discoveryOpenUrl(payload) { return request(endpoint('discoveryOpenUrl'), { method:'POST', body:payload, timeoutMs:65000 }); },
    languages() { return request(endpoint('languages')); },
    methods() { return request(endpoint('methods')); },
    execute(payload) { return request(endpoint('execute'), { method:'POST', body:payload }); },
    compare(payload) { return request(endpoint('compare'), { method:'POST', body:payload, timeoutMs:65000 }); },
    validateReport(payload) { return request(endpoint('reportValidate'), { method:'POST', body:payload, timeoutMs:65000 }); },
    reportPdf(payload) { return request(endpoint('reportPdf'), { method:'POST', body:payload, timeoutMs:65000 }); },
    validateHandoff(packet) { return request(endpoint('handoffValidate'), { method:'POST', body:{ packet }, timeoutMs:65000 }); },
